/** Independent test-only parser/evaluator for the published spreadsheet subset.
 * No generator or production function is imported. */
import assert from 'node:assert/strict';
export type Scalar=number|string|boolean|null;
export type Address={kind:'ref';sheet:string;column:number;row:number;absoluteRow:boolean};
export type Expr={kind:'literal';value:Scalar}|Address|{kind:'range';from:Address;to:Address}|{kind:'variable';name:string}|{kind:'call';name:string;args:Expr[]}|{kind:'binary';op:string;left:Expr;right:Expr}|{kind:'unary';operand:Expr};
type Range={kind:'range-value';from:Address;to:Address};
export type Environment={get:(sheet:string,row:number,column:number)=>Scalar;variables?:Record<string,Scalar>;copyRows?:number};
function address(token:string,sheet=''):Address{const m=token.match(/^\$?([A-Z]+)(\$?)(\d+)$/);assert(m,'cell '+token);return{kind:'ref',sheet,column:[...m[1]].reduce((n,c)=>n*26+c.charCodeAt(0)-64,0),row:Number(m[3]),absoluteRow:m[2]==='$'};}
export function readSpringPm13Expression(text:string):Expr{const tokens:string[]=[];let remaining=text;while(remaining.length){remaining=remaining.trimStart();if(!remaining)break;const m=remaining.match(/^(?:\d+(?:\.\d+)?|'[^']*'|\$?[A-Z]+\$?\d+|[\p{L}_][\p{L}\p{N}_]*|[(),:!+\-/=<>≥≤≠])/u);assert(m,'token '+remaining);tokens.push(m[0]);remaining=remaining.slice(m[0].length);}let at=0;const take=()=>{assert(at<tokens.length);return tokens[at++];},expect=(s:string)=>assert.equal(take(),s);
 function primary():Expr{let t=take();if(t==='-')return{kind:'unary',operand:primary()};if(t==='('){const n=comparison();expect(')');return n;}if(/^\d/.test(t))return{kind:'literal',value:Number(t)};if(t.startsWith("'"))return{kind:'literal',value:t.slice(1,-1)};if(tokens[at]==='('){at++;const args:Expr[]=[];if(tokens[at]!==')'){do{args.push(comparison());if(tokens[at]!==',')break;at++;}while(true);}expect(')');return{kind:'call',name:t,args};}let sheet='';if(tokens[at]==='!'){at++;sheet=t;t=take();}if(/^\$?[A-Z]+\$?\d+$/.test(t)){const from=address(t,sheet);if(tokens[at]===':'){at++;return{kind:'range',from,to:address(take(),sheet)};}return from;}if(t==='null')return{kind:'literal',value:null};return{kind:'variable',name:t};}
 function multiply():Expr{let n=primary();while(tokens[at]==='/'){const op=take();n={kind:'binary',op,left:n,right:primary()};}return n;}
 function add():Expr{let n=multiply();while(tokens[at]==='+'||tokens[at]==='-'){const op=take();n={kind:'binary',op,left:n,right:multiply()};}return n;}
 function comparison():Expr{const left=add();if(['=','≠','>','<','≥','≤'].includes(tokens[at])){const op=take();return{kind:'binary',op,left,right:add()};}return left;}
 const result=comparison();assert.equal(at,tokens.length,'trailing expression tokens');return result;}
function number(value:Scalar|Range):number{assert.equal(typeof value,'number');assert(Number.isFinite(value));return value as number;}
function scalar(value:Scalar|Range):Scalar{assert(typeof value!=='object'||value===null);return value as Scalar;}
function ref(node:Address,env:Environment):Address{return{...node,row:node.row+(node.absoluteRow?0:env.copyRows??0)};}
function rangeAt(r:Range,index:number,column:number,env:Environment){assert(Number.isInteger(index)&&index>=1&&index<=r.to.row-r.from.row+1);assert(Number.isInteger(column)&&column>=1&&column<=r.to.column-r.from.column+1);return env.get(r.from.sheet,r.from.row+index-1,r.from.column+column-1);}
function values(r:Range,env:Environment){assert.equal(r.from.column,r.to.column);return Array.from({length:r.to.row-r.from.row+1},(_,i)=>rangeAt(r,i+1,1,env));}
function asRange(value:Scalar|Range):Range{assert(value&&typeof value==='object'&&value.kind==='range-value');return value;}
export function evaluateSpringPm13Expression(node:Expr,env:Environment):Scalar|Range{if(node.kind==='literal')return node.value;if(node.kind==='variable'){assert(env.variables&&Object.hasOwn(env.variables,node.name),'variable '+node.name);return env.variables[node.name];}if(node.kind==='ref'){const r=ref(node,env);return env.get(r.sheet,r.row,r.column);}if(node.kind==='range')return{kind:'range-value',from:ref(node.from,env),to:ref(node.to,env)};if(node.kind==='unary')return-number(evaluateSpringPm13Expression(node.operand,env));if(node.kind==='binary'){const a=scalar(evaluateSpringPm13Expression(node.left,env)),b=scalar(evaluateSpringPm13Expression(node.right,env));if(node.op==='=')return a===b;if(node.op==='≠')return a!==b;if(node.op==='+')return number(a)+number(b);if(node.op==='-')return number(a)-number(b);if(node.op==='/'){assert.notEqual(number(b),0);return number(a)/number(b);}const x=number(a),y=number(b);return node.op==='>'?x>y:node.op==='<'?x<y:node.op==='≥'?x>=y:x<=y;}
 const args=node.args.map(a=>evaluateSpringPm13Expression(a,env));switch(node.name){case'論理積':assert(args.every(a=>typeof a==='boolean'));return args.every(Boolean);case'論理和':assert(args.every(a=>typeof a==='boolean'));return args.some(Boolean);case'否定':assert.equal(args.length,1);assert.equal(typeof args[0],'boolean');return!args[0];case'最大':return Math.max(...values(asRange(args[0]),env).map(number));case'最小':return Math.min(...values(asRange(args[0]),env).map(number));case'IF':assert.equal(typeof args[0],'boolean');return args[0]?args[1]:args[2];case'表引き':return rangeAt(asRange(args[0]),number(args[1]),number(args[2]),env);case'照合一致':{const all=values(asRange(args[1]),env),wanted=scalar(args[0]),mode=number(args[2]);assert(mode===0||mode===1);if(mode===0){const found=all.indexOf(wanted);assert(found>=0,'not found');return found+1;}assert(all.every((v,i)=>typeof v==='number'&&(i===0||number(all[i-1])<=v)),'ascending lookup precondition');const possible=all.flatMap((v,i)=>number(v)<=number(wanted)?[i]:[]);assert(possible.length);const greatest=Math.max(...possible.map(i=>number(all[i])));return all.indexOf(greatest)+1;}case'照合検索':{const search=values(asRange(args[1]),env),extract=values(asRange(args[2]),env);assert.equal(search.length,extract.length);const i=search.indexOf(scalar(args[0]));assert(i>=0);return extract[i];}case'順位':{const all=values(asRange(args[1]),env).map(number),wanted=number(args[0]),order=number(args[2]);assert(order===0||order===1);return 1+all.filter(v=>order===0?v<wanted:v>wanted).length;}case'相対':{const a=resolveSpringPm13Write(node,env);return env.get(a.sheet,a.row,a.column);}default:throw Error('unknown function '+node.name);}}
export function resolveSpringPm13Write(node:Expr,env:Environment):Address{assert(node.kind==='call'&&node.name==='相対');assert.equal(node.args.length,3);const base=node.args[0];assert(base.kind==='ref');const a=ref(base,env),row=number(evaluateSpringPm13Expression(node.args[1],env)),column=number(evaluateSpringPm13Expression(node.args[2],env));assert(Number.isInteger(row)&&Number.isInteger(column));return{...a,row:a.row+row,column:a.column+column};}
